// The skeleton of the app was generated by claude 
// Some clean up was done by claude as well

import { FormEvent, useEffect, useState } from "react";
import "./App.css";

const API = "http://localhost:3000/api";
const EMAIL_STORAGE_KEY = "checkout-demo-email";

type Listing = {
  id: string;
  eventName: string;
  date: string;
  price: number;
  available: number;
  held: number;
  purchasable: number;
};

type ApiError = Error & {
  available?: number;
  sessionId?: string;
  retryable?: boolean;
};

type Session = {
  id: string;
  listingId: string;
  quantity: number;
  agreedPrice: number;
  priceAccepted: boolean;
  status:
    | "ACTIVE"
    | "PAYMENT_PENDING"
    | "COMPLETED"
    | "EXPIRED"
    | "FAILED";
  userEmail: string;
  createdAt: number;
  expiresAt: number;
  orderId?: string;
};

type SessionRow = {
  session: Session;
  listing: Listing;
};

type View = "signin" | "dashboard" | "checkout";

const price = (cents: number) =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);

const priceReviewMessage =
  "The ticket price changed. Review and accept the latest price.";

function isOpenStatus(status: Session["status"]) {
  return status === "ACTIVE" || status === "PAYMENT_PENDING";
}

type ActionLink = {
  label: string;
  onClick: () => void;
  disabled?: boolean;
};

const closedCheckout: Partial<
  Record<Session["status"], { title: string; body: string }>
> = {
  EXPIRED: {
    title: "Checkout expired",
    body: "This session is no longer valid. Tickets and prices must be checked again before starting a new checkout.",
  },
  FAILED: {
    title: "Payment unsuccessful",
    body: "No order was created, and the reserved tickets were released. Start a new checkout to try again.",
  },
};

function statusLabel(status: string) {
  return status.replace("_", " ");
}

function errorText(err: unknown, fallback: string) {
  return err instanceof Error ? err.message : fallback;
}

function ticketLabel(count: number) {
  return `${count} ticket${count === 1 ? "" : "s"}`;
}

function formatTime(seconds: number) {
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

function searchSessionId() {
  return new URLSearchParams(window.location.search).get("session");
}

function ActionLinks({
  links,
  disabled = false,
}: {
  links: ActionLink[];
  disabled?: boolean;
}) {
  return (
    <>
      {links.map((link) => (
        <button
          key={link.label}
          className="text-button"
          onClick={link.onClick}
          disabled={disabled || link.disabled}
        >
          {link.label}
        </button>
      ))}
    </>
  );
}

function readStoredEmail() {
  return window.localStorage.getItem(EMAIL_STORAGE_KEY) ?? "";
}

function inventoryMessage(available?: number) {
  if (available === 0) {
    return "This event is sold out. No more tickets can be purchased.";
  }

  if (typeof available === "number") {
    const noun = available === 1 ? "ticket is" : "tickets are";
    return `Only ${available} ${noun} left, so this quantity can't be purchased.`;
  }

  return "There aren't enough tickets left to complete this order.";
}

function checkoutError(err: unknown, fallback: string) {
  const message = errorText(err, fallback);

  if (message === "PRICE_CHANGED") return priceReviewMessage;

  if (message === "INVENTORY_UNAVAILABLE") {
    return inventoryMessage(
      err instanceof Error ? (err as ApiError).available : undefined,
    );
  }

  if (message === "PAYMENT_FAILED") {
    return (err as ApiError).retryable === false
      ? "Payment failed. The reserved tickets were released."
      : "Payment failed. Please try again.";
  }

  return message;
}

export default function App() {
  const [view, setView] = useState<View>("signin");
  const [userEmail, setUserEmail] = useState("");
  const [emailInput, setEmailInput] = useState("");
  const [listing, setListing] = useState<Listing | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [sessions, setSessions] = useState<SessionRow[]>([]);
  const [currentPrice, setCurrentPrice] = useState(0);
  const [quantity, setQuantity] = useState(2);
  const [remaining, setRemaining] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  async function request<T>(
    path: string,
    options?: RequestInit,
  ): Promise<T> {
    const signedInEmail = readStoredEmail();

    const response = await fetch(`${API}${path}`, {
      ...options,
      cache: "no-store",
      headers: {
        "Content-Type": "application/json",
        ...(signedInEmail ? { "X-Demo-Email": signedInEmail } : {}),
        ...options?.headers,
      },
    });

    const data = await response.json();

    if (!response.ok) {
      const error = new Error(
        data.error ?? "Something went wrong.",
      ) as ApiError;
      error.available = data.available;
      error.sessionId = data.sessionId;
      error.retryable = data.retryable;
      throw error;
    }

    return data as T;
  }

  async function loadListing() {
    const data = await request<{ listing: Listing }>(
      "/listings/listing-1",
    );

    setListing(data.listing);
    setCurrentPrice(data.listing.price);
  }

  async function loadDashboard(email: string) {
    const data = await request<{ sessions: SessionRow[] }>(
      "/checkout-sessions",
      { headers: { "X-Demo-Email": email } },
    );

    setSessions(data.sessions);
  }

  function signInWithEmail(email: string) {
    window.localStorage.setItem(EMAIL_STORAGE_KEY, email);
    setUserEmail(email);
    setEmailInput(email);
  }

  async function resumeSession(id: string, silent = false) {
    if (!silent) {
      setLoading(true);
      setError("");
      setNotice("");
    }

    try {
      const data = await request<{
        session: Session;
        listing: Listing;
        currentPrice: number;
      }>(`/checkout-sessions/${id}`);

      const signedInAs = readStoredEmail();

      if (!signedInAs || data.session.userEmail !== signedInAs) {
        throw new Error("SESSION_FORBIDDEN");
      }

      window.history.pushState({}, "", `?session=${id}`);

      setSession(data.session);
      setListing(data.listing);
      setCurrentPrice(data.currentPrice);
      setView("checkout");
      setRemaining(
        Math.max(
          0,
          Math.ceil(
            (data.session.expiresAt - Date.now()) / 1000,
          ),
        ),
      );
    } catch (err) {
      if (silent) return;

      const code = errorText(err, "");
      const signedInAs = readStoredEmail();

      if (code === "SESSION_FORBIDDEN" && signedInAs) {
        setError(
          `This checkout belongs to another account. You're still signed in as ${signedInAs}.`,
        );
        await goToDashboard(signedInAs, true);
        return;
      }

      if (code === "UNAUTHENTICATED" || !signedInAs) {
        setView("signin");
        setError("Sign in with the demo email that started this checkout.");
        return;
      }

      setError(code || "Unable to resume checkout.");
    } finally {
      if (!silent) setLoading(false);
    }
  }

  async function goToDashboard(email = userEmail, preserveError = false) {
    if (!email) {
      setView("signin");
      return;
    }

    setLoading(true);
    if (!preserveError) setError("");
    setNotice("");
    setSession(null);
    window.history.pushState({}, "", "/");

    try {
      await Promise.all([loadListing(), loadDashboard(email)]);
      setView("dashboard");
    } catch (err) {
      setError(errorText(err, "Unable to load dashboard."));
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const sessionId = params.get("session");
    const storedEmail = readStoredEmail();

    if (storedEmail) {
      setUserEmail(storedEmail);
      setEmailInput(storedEmail);
    }

    if (sessionId) {
      if (!storedEmail) {
        setView("signin");
        return;
      }

      void resumeSession(sessionId);
      return;
    }

    if (storedEmail) {
      void goToDashboard(storedEmail);
      return;
    }

    void loadListing().catch((err) => {
      setError(errorText(err, "Unable to load event."));
    });
  }, []);

  useEffect(() => {
    if (!session || session.status !== "ACTIVE") return;

    const sessionId = session.id;
    const expiresAt = session.expiresAt;

    function updateCountdown() {
      const nextRemaining = Math.max(
        0,
        Math.ceil((expiresAt - Date.now()) / 1000),
      );

      setRemaining(nextRemaining);

      if (nextRemaining === 0) {
        void resumeSession(sessionId, true);
      }
    }

    updateCountdown();

    const timer = window.setInterval(updateCountdown, 1000);

    return () => window.clearInterval(timer);
  }, [session?.id, session?.status, session?.expiresAt]);

  useEffect(() => {
    if (!session || !isOpenStatus(session.status)) {
      return;
    }

    const timer = window.setInterval(async () => {
      try {
        await resumeSession(session.id, true);
      } catch (pollError) {
        console.error("Failed to sync session:", pollError);
      }
    }, 3000);

    return () => window.clearInterval(timer);
  }, [session?.id, session?.status]);

  async function signIn(event: FormEvent) {
    event.preventDefault();

    const email = emailInput.trim().toLowerCase();

    if (!email.includes("@")) {
      setError("Enter a demo email to continue.");
      return;
    }

    signInWithEmail(email);

    const pendingSession = searchSessionId();

    if (pendingSession) {
      await resumeSession(pendingSession);
      return;
    }

    await goToDashboard(email);
  }

  function signOut() {
    window.localStorage.removeItem(EMAIL_STORAGE_KEY);
    setUserEmail("");
    setEmailInput("");
    setSession(null);
    setSessions([]);
    setView("signin");
    setError("");
    setNotice("");
    window.history.pushState({}, "", "/");
  }

  async function startCheckout() {
    if (!userEmail) {
      setView("signin");
      setError("Sign in with a demo email before starting checkout.");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await request<{
        session: Session;
        listing: Listing;
      }>("/checkout-sessions", {
        method: "POST",
        body: JSON.stringify({
          listingId: "listing-1",
          quantity: Math.min(quantity, ticketsLeft),
        }),
      });

      await resumeSession(data.session.id);
    } catch (err) {
      const openSessionId =
        err instanceof Error ? (err as ApiError).sessionId : undefined;

      if (
        err instanceof Error &&
        err.message === "CHECKOUT_ALREADY_OPEN" &&
        openSessionId
      ) {
        await resumeSession(openSessionId);
        setNotice("You already have a checkout open for this event.");
      } else if (
        err instanceof Error &&
        err.message === "INVENTORY_UNAVAILABLE"
      ) {
        setError(checkoutError(err, "Unable to start checkout."));
        await loadListing().catch(() => undefined);
      } else {
        setError(errorText(err, "Unable to start checkout."));
      }
    } finally {
      setLoading(false);
    }
  }

  async function acceptPrice() {
    if (!session) return;

    setLoading(true);
    setError("");

    try {
      await request(
        `/checkout-sessions/${session.id}/accept-price`,
        {
          method: "POST",
          body: JSON.stringify({ expectedPrice: currentPrice }),
        },
      );

      await resumeSession(session.id);
      setNotice("Updated price accepted.");
    } catch (err) {
      const message = checkoutError(err, "Unable to accept price.");

      await resumeSession(session.id);

      setError(message);
    } finally {
      setLoading(false);
    }
  }

  async function completeCheckout(
    outcome: "success" | "failure" | "pending" = "success",
  ) {
    if (!session) return;

    setLoading(true);
    setError("");
    setNotice("");

    try {
      const data = await request<{
        session: Session;
        order?: { id: string; total: number };
      }>(`/checkout-sessions/${session.id}/complete`, {
        method: "POST",
        body: JSON.stringify({
          simulatePaymentFailure: outcome === "failure",
          simulatePaymentPending: outcome === "pending",
        }),
      });

      setSession(data.session);

      if (data.order) {
        setNotice(`Order confirmed: ${data.order.id}`);
      } else if (data.session.status === "PAYMENT_PENDING") {
        setNotice("Payment submitted. Waiting for confirmation.");
      }
    } catch (err) {
      await resumeSession(session.id);
      setError(checkoutError(err, "Unable to complete checkout."));
    } finally {
      setLoading(false);
    }
  }

  async function runDev(task: () => Promise<void>, fallback: string) {
    setError("");

    try {
      await task();
    } catch (err) {
      setError(errorText(err, fallback));
    }
  }

  async function changePrice() {
    await runDev(async () => {
      await request("/dev/listings/listing-1/price", {
        method: "PATCH",
        body: JSON.stringify({ price: 15_000 }),
      });

      if (session) await resumeSession(session.id);
      else setCurrentPrice(15_000);

      setNotice("Listing price changed to $150.");
    }, "Unable to change price.");
  }

  async function setInventory(available: number) {
    await runDev(async () => {
      await request("/dev/listings/listing-1/inventory", {
        method: "PATCH",
        body: JSON.stringify({ available }),
      });

      if (session) await resumeSession(session.id);
      else await loadListing();

      setNotice(
        available === 0
          ? "Inventory is sold out."
          : `Inventory restored to ${available} tickets.`,
      );
    }, "Unable to update inventory.");
  }

  async function expireSession() {
    if (!session) return;

    await runDev(async () => {
      await request(`/dev/sessions/${session.id}/expire`, {
        method: "POST",
      });

      await resumeSession(session.id);
    }, "Unable to expire session.");
  }

  const priceChanged =
    !!session && currentPrice !== session.agreedPrice;

  const openCheckout = sessions.find(({ session: row }) =>
    isOpenStatus(row.status),
  );
  const ticketsLeft = listing?.purchasable ?? listing?.available ?? 0;
  const quantityChoices = Array.from(
    { length: Math.min(4, ticketsLeft) },
    (_, index) => index + 1,
  );
  const inventoryShort =
    !!session &&
    isOpenStatus(session.status) &&
    ticketsLeft < session.quantity;
  const canSimulatePayment =
    session?.status === "ACTIVE" &&
    !priceChanged &&
    !inventoryShort &&
    remaining > 0;
  const closed = session ? closedCheckout[session.status] : undefined;
  const inventoryLinks: ActionLink[] = [
    { label: "Simulate sold out", onClick: () => void setInventory(0) },
    { label: "Restore 20 tickets", onClick: () => void setInventory(20) },
  ];
  const simulationLinks: ActionLink[] = [
    {
      label: "Simulate price increase to $150",
      onClick: () => void changePrice(),
    },
    {
      label: "Simulate session expiration",
      onClick: () => void expireSession(),
      disabled: !session || !isOpenStatus(session.status),
    },
    ...(session?.status === "ACTIVE"
      ? [
          {
            label: "Simulate payment failure",
            onClick: () => void completeCheckout("failure"),
            disabled: !canSimulatePayment,
          },
          {
            label: "Simulate payment pending",
            onClick: () => void completeCheckout("pending"),
            disabled: !canSimulatePayment,
          },
        ]
      : []),
    ...(session?.status === "PAYMENT_PENDING"
      ? [
          {
            label: "Resolve payment as successful",
            onClick: () => void completeCheckout("success"),
            disabled: priceChanged || inventoryShort,
          },
          {
            label: "Resolve payment as failed",
            onClick: () => void completeCheckout("failure"),
          },
        ]
      : []),
    ...inventoryLinks,
  ];

  return (
    <main className="app-shell">
      <header className="topbar">
        <a className="brand" href="/" onClick={(event) => {
          event.preventDefault();
          if (userEmail) void goToDashboard(userEmail);
          else setView("signin");
        }}>
          GAMETIME
        </a>

        {userEmail ? (
          <div className="topbar-actions">
            <span className="secure-label">{userEmail}</span>
            <button className="text-button topbar-link" onClick={signOut}>
              Sign out
            </button>
          </div>
        ) : (
          <span className="secure-label">Demo checkout</span>
        )}
      </header>

      <div className="page-content">
        {error && <div className="alert error">{error}</div>}
        {notice && <div className="alert success">{notice}</div>}

        {loading && (
          <p className="loading" role="status">
            Updating checkout…
          </p>
        )}

        {view === "signin" && (
          <section className="auth-card">
            <p className="eyebrow">DEMO SIGN-IN</p>
            <h1>Continue with a demo email</h1>
            <p className="muted">
              {searchSessionId()
                ? "Sign in with the demo email that started this checkout. A resume link stays locked to that account."
                : "No password needed. This demo email is your account, and you can only open checkouts that belong to it."}
            </p>

            <form className="sign-in-form" onSubmit={signIn}>
              <label htmlFor="demo-email">Demo email</label>
              <input
                id="demo-email"
                type="email"
                autoComplete="email"
                placeholder="you@example.com"
                value={emailInput}
                onChange={(event) => setEmailInput(event.target.value)}
              />
              <button className="primary-button" type="submit" disabled={loading}>
                Continue
              </button>
            </form>
          </section>
        )}

        {view === "dashboard" && (
          <section className="dashboard">
            <div className="dashboard-header">
              <div>
                <p className="eyebrow">YOUR ACCOUNT</p>
                <h1>Checkout dashboard</h1>
                <p className="muted">
                  Resume an existing session instead of starting over.
                </p>
              </div>
            </div>

            <div className="session-list">
              {sessions.length === 0 ? (
                <div className="state-card">
                  <h2>No checkout sessions yet</h2>
                  <p>Start a new checkout from the event below.</p>
                </div>
              ) : (
                sessions.map(({ session: row, listing: rowListing }) => (
                  <article className="session-row" key={row.id}>
                    <div>
                      <p className="eyebrow">{statusLabel(row.status)}</p>
                      <h2>{rowListing.eventName}</h2>
                      <p className="muted">
                        {ticketLabel(row.quantity)} ·{" "}
                        {price(row.agreedPrice * row.quantity)}
                      </p>
                    </div>
                    <button
                      className="primary-button"
                      onClick={() => void resumeSession(row.id)}
                      disabled={loading}
                    >
                      Resume checkout
                    </button>
                  </article>
                ))
              )}
            </div>

            {listing && (
              <section className="event-card">
                <div className="event-art">
                  <span>LIVE</span>
                  <h2>THE NIGHT<br />IS YOURS.</h2>
                  <p>DALLAS · LIVE MUSIC</p>
                </div>

                <div className="event-details">
                  <p className="eyebrow">FEATURED EVENT</p>
                  <h1>{listing.eventName}</h1>
                  <p className="muted">{listing.date} · Dallas, TX</p>

                  <div className="event-footer">
                    <div>
                      <p className="muted">Tickets from</p>
                      <strong>{price(listing.price)}</strong>
                      <p className="muted">
                        {ticketsLeft === 0
                          ? "Sold out"
                          : `${ticketLabel(ticketsLeft)} left`}
                      </p>
                    </div>

                    {ticketsLeft > 0 && (
                      <label className="quantity-control">
                        Quantity
                        <select
                          value={Math.min(quantity, ticketsLeft)}
                          onChange={(event) =>
                            setQuantity(Number(event.target.value))
                          }
                        >
                          {quantityChoices.map((n) => (
                            <option key={n} value={n}>{n}</option>
                          ))}
                        </select>
                      </label>
                    )}
                  </div>

                  {ticketsLeft === 0 ? (
                    <div className="alert warning">
                      <strong>Sold out.</strong>
                      <p>
                        There are no tickets left for this event, so a new
                        checkout can't be started.
                      </p>
                    </div>
                  ) : (
                    <button
                      className="primary-button"
                      onClick={() => {
                        if (openCheckout) {
                          void resumeSession(openCheckout.session.id);
                          return;
                        }

                        void startCheckout();
                      }}
                      disabled={loading || (!openCheckout && quantity > ticketsLeft)}
                    >
                      {openCheckout ? "Resume checkout" : "Start new checkout"}
                    </button>
                  )}

                  <div className="dev-tools">
                    <p className="eyebrow">DEMO CONTROLS</p>
                    <ActionLinks links={inventoryLinks} disabled={loading} />
                  </div>
                </div>
              </section>
            )}
          </section>
        )}

        {view === "checkout" && session && listing && (
          <section className="checkout-layout">
            <div className="checkout-main">
              <button
                className="text-button"
                onClick={() => void goToDashboard(userEmail)}
              >
                ← Back to dashboard
              </button>
              <p className="eyebrow">YOUR CHECKOUT</p>
              <h1>{listing.eventName}</h1>
              <p className="muted">{listing.date} · Dallas, TX</p>

              <div className="session-strip">
                <div>
                  <span className="muted">Session status</span>
                  <strong>{statusLabel(session.status)}</strong>
                </div>

                {session.status === "ACTIVE" && (
                  <div>
                    <span className="muted">Session countdown</span>
                    <strong>{formatTime(remaining)}</strong>
                  </div>
                )}
              </div>

              {priceChanged && isOpenStatus(session.status) && (
                <div className="alert warning">
                  <strong>The ticket price has changed.</strong>
                  <p>
                    Previous price: {price(session.agreedPrice)} per ticket.
                    <br />
                    New price: {price(currentPrice)} per ticket.
                  </p>
                  <p>Review and accept the new price before continuing.</p>
                  <button
                    className="primary-button"
                    onClick={acceptPrice}
                    disabled={loading}
                  >
                    Accept new price
                  </button>
                </div>
              )}

              {inventoryShort && (
                <div className="alert warning">
                  <strong>Not enough tickets left.</strong>
                  <p>{inventoryMessage(ticketsLeft)}</p>
                  <p>No order was created, so nothing was sold past the remaining inventory.</p>
                </div>
              )}

              {session.status === "ACTIVE" && !priceChanged && !inventoryShort && (
                <div className="ticket-summary">
                  <h2>Order summary</h2>
                  <div className="summary-row">
                    <span>Tickets × {session.quantity}</span>
                    <span>{price(session.agreedPrice * session.quantity)}</span>
                  </div>
                  <div className="summary-row">
                    <span>Fees</span>
                    <span>Included in demo</span>
                  </div>
                  <div className="summary-row total">
                    <span>Total</span>
                    <span>{price(session.agreedPrice * session.quantity)}</span>
                  </div>

                  <button
                    className="primary-button"
                    onClick={() => completeCheckout()}
                    disabled={loading || !canSimulatePayment}
                  >
                    Complete checkout
                  </button>
                </div>
              )}

              {session.status === "COMPLETED" && (
                <div className="state-card success-state">
                  <h2>You're all set!</h2>
                  <p>Your order has been confirmed.</p>
                  <p>Order ID: {session.orderId}</p>
                </div>
              )}

              {closed && (
                <div className="state-card">
                  <h2>{closed.title}</h2>
                  <p>{closed.body}</p>
                  <button
                    className="primary-button"
                    onClick={() => void goToDashboard(userEmail)}
                  >
                    Back to dashboard
                  </button>
                </div>
              )}

              {session.status === "PAYMENT_PENDING" && (
                <div className="state-card">
                  <h2>Payment processing</h2>
                  <p>
                    The payment was submitted and is waiting for confirmation.
                    No order has been created yet, and these tickets stay reserved.
                  </p>
                  <p>
                    Keep this checkout open, or resume it from the dashboard.
                    Refreshing checks the same session instead of starting a new one.
                  </p>
                  <button
                    className="secondary-button"
                    onClick={() => void resumeSession(session.id)}
                    disabled={loading}
                  >
                    Refresh payment status
                  </button>
                </div>
              )}
            </div>

            <aside className="resume-panel">
              <label className="share-label" htmlFor="resume-url">
                Resume link
              </label>
              <input
                id="resume-url"
                readOnly
                value={`${window.location.origin}/?session=${session.id}`}
                onFocus={(event) => event.currentTarget.select()}
              />

              <div className="sim-links">
                <ActionLinks links={simulationLinks} disabled={loading} />
              </div>
            </aside>
          </section>
        )}
      </div>
    </main>
  );
}
